Signed-off-by: Thomas Hellström <thomas.hellstrom@linux.intel.com>

Here is the root cause:
The bug is caused by removing the buffer object (BO) from its bulk move group (via `ttm_resource_del_bulk_move`) before the backup operation. If the backup fails, the code attempts to re-add the BO to the bulk move group, but this leaves the LRU state inconsistent, resulting in an infinite LRU walk during shrinking. The fix moves the bulk move deletion to occur only after a successful backup, ensuring the BO remains correctly linked in the LRU on failure.

Here is the patch:
  */
 long ttm_bo_shrink(struct ttm_operation_ctx *ctx, struct ttm_buffer_object *bo,
 		   const struct ttm_bo_shrink_flags flags)
 {
 	static const struct ttm_place sys_placement_flags = {
 		.fpfn = 0,
 		.lpfn = 0,
 		.mem_type = TTM_PL_SYSTEM,
 		.flags = 0,
 	};
 	static struct ttm_placement sys_placement = {
 		.num_placement = 1,
 		.placement = &sys_placement_flags,
 	};
 	struct ttm_device *bdev = bo->bdev;
 	long lret;

 	dma_resv_assert_held(bo->base.resv);

 	if (flags.allow_move && bo->resource->mem_type != TTM_PL_SYSTEM) {
 		int ret = ttm_bo_validate(bo, &sys_placement, ctx);

 		/* Consider -ENOMEM and -ENOSPC non-fatal. */
 		if (ret) {
 			if (ret == -ENOMEM || ret == -ENOSPC)
 				ret = -EBUSY;
 			return ret;
 		}
 	}

 	ttm_bo_unmap_virtual(bo);
 	lret = ttm_bo_wait_ctx(bo, ctx);
 	if (lret < 0)
 		return lret;

-	if (bo->bulk_move) {
-		spin_lock(&bdev->lru_lock);
-		ttm_resource_del_bulk_move(bo->resource, bo);
-		spin_unlock(&bdev->lru_lock);
-	}
-
 	lret = ttm_tt_backup(bdev, bo->ttm, (struct ttm_backup_flags)
 			     {.purge = flags.purge,
 			      .writeback = flags.writeback});

-	if (lret <= 0 && bo->bulk_move) {
+	if (lret > 0) {
 		spin_lock(&bdev->lru_lock);
-		ttm_resource_add_bulk_move(bo->resource, bo);
+		ttm_resource_del_bulk_move_unevictable(bo->resource, bo);
+		ttm_resource_move_to_lru_tail(bo->resource);
 		spin_unlock(&bdev->lru_lock);
 	}

 	if (lret < 0 && lret != -EINTR)
 		return -EBUSY;

 	return lret;
 }
 EXPORT_SYMBOL(ttm_bo_shrink);


